    def test_crossdomain_automatic_options(self):

        # On plain Flask views, automatic OPTIONS preflights are
        # short-circuited by the decorator and carry the CORS headers.
        app = Flask(__name__)

        @app.route('/', methods=['GET', 'OPTIONS'])
        @cors.crossdomain(origin='*')
        def view():
            return "data"

        with app.test_client() as client:
            res = client.options('/')
            self.assertEqual(res.status_code, 200)
            self.assertEqual(res.headers['Access-Control-Allow-Origin'], '*')
